import json
from pathlib import Path
import sys


def search_key(title):
    return title.casefold()


def load(path="data/books.json"):
    return json.loads(Path(path).read_text())


def build_export(rows):
    """Rows keyed by (isbn, edition); sorted by displayed title, isbn, edition."""
    books = [
        {"isbn": r["isbn"], "edition": r["edition"], "title": r["title"],
         "active": r["active"], "key": search_key(r["title"])}
        for r in rows
    ]
    books.sort(key=lambda b: (b["title"], b["isbn"], b["edition"]))
    return {"books": books}


def write_export(path="build/search.json", source="data/books.json"):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(build_export(load(source)), ensure_ascii=False, indent=2) + "\n",
                    encoding="utf-8")
    return path


def search(prefix, books):
    needle = search_key(prefix)
    return [b for b in books if b["key"].startswith(needle)]


if __name__ == "__main__":
    args = sys.argv[1:]
    if args[:1] == ["export"]:
        print(write_export(*args[1:2]))
    elif args[:1] == ["search"] and len(args) == 2:
        for b in search(args[1], build_export(load())["books"]):
            print(json.dumps(b, ensure_ascii=False))
    else:
        rows = load()
        print(json.dumps({"rows": len(rows), "unique_isbns": len({r["isbn"] for r in rows}),
                          "keys": [search_key(r["title"]) for r in rows]}, ensure_ascii=False))
EOF
